Fixpoint inzr (i : Z) (l : list (Z * Z)) : bool :=
  match l with
  | [] => false
  | (lo, hi) :: r => ((lo <=? i) && (i <? hi)) || inzr i r
  end.

Definition zf (m : word -> option byte) (d : Z) (l : list (Z * Z)) : word -> option byte :=
  fun x => if inzr (bv_unsigned x - d) l then Some (Z_to_bv 8 0) else m x.

